-- etl-craft: rebuild-metadata
DROP VIEW IF EXISTS AUD_METADATA_CHANGES;
CREATE TABLE CFG_PIPELINE_GRANTS_new (
    PIPELINE_GRANT_ID INTEGER PRIMARY KEY AUTOINCREMENT,
    GROUP_ID BIGINT REFERENCES CFG_GROUPS(GROUP_ID),
    ACCOUNT_ID BIGINT REFERENCES CFG_ACCOUNTS(ACCOUNT_ID),
    GRANTEE_ROLE VARCHAR(16) CHECK (GRANTEE_ROLE IN ('viewer','operator')),
    PIPELINE_CODE VARCHAR,
    TAG VARCHAR,
    PERMISSION VARCHAR(16) NOT NULL CHECK (PERMISSION IN ('CAN_VIEW','CAN_RUN','CAN_MANAGE')),
    ACTIVE_FLAG VARCHAR(1) NOT NULL DEFAULT 'Y' CHECK (ACTIVE_FLAG IN ('Y','N')),
    CREATED_BY VARCHAR(128) NOT NULL DEFAULT 'etl-craft',
    CREATE_DATE TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UPDATED_BY VARCHAR(128) NOT NULL DEFAULT 'etl-craft',
    UPDATED_DATE TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PROJECT_ID BIGINT NOT NULL DEFAULT 1 REFERENCES CFG_PROJECTS(PROJECT_ID),
    FOREIGN KEY (PROJECT_ID,PIPELINE_CODE) REFERENCES CFG_PIPELINES(PROJECT_ID,PIPELINE_CODE),
    CHECK ((CASE WHEN GROUP_ID IS NULL THEN 0 ELSE 1 END +
            CASE WHEN ACCOUNT_ID IS NULL THEN 0 ELSE 1 END +
            CASE WHEN GRANTEE_ROLE IS NULL THEN 0 ELSE 1 END)=1),
    CHECK (PIPELINE_CODE IS NULL OR TAG IS NULL)
);
INSERT INTO CFG_PIPELINE_GRANTS_new (PIPELINE_GRANT_ID,GROUP_ID,ACCOUNT_ID,GRANTEE_ROLE,PIPELINE_CODE,TAG,PERMISSION,ACTIVE_FLAG,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,PROJECT_ID) SELECT PIPELINE_GRANT_ID,GROUP_ID,ACCOUNT_ID,GRANTEE_ROLE,PIPELINE_CODE,TAG,PERMISSION,ACTIVE_FLAG,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,PROJECT_ID FROM CFG_PIPELINE_GRANTS;
DROP TABLE CFG_PIPELINE_GRANTS;
ALTER TABLE CFG_PIPELINE_GRANTS_new RENAME TO CFG_PIPELINE_GRANTS;
CREATE UNIQUE INDEX ux_pipeline_grant_code ON CFG_PIPELINE_GRANTS (PROJECT_ID,GROUP_ID,PIPELINE_CODE) WHERE ACTIVE_FLAG='Y' AND GROUP_ID IS NOT NULL AND PIPELINE_CODE IS NOT NULL;
CREATE UNIQUE INDEX ux_pipeline_grant_tag ON CFG_PIPELINE_GRANTS (PROJECT_ID,GROUP_ID,TAG) WHERE ACTIVE_FLAG='Y' AND GROUP_ID IS NOT NULL AND TAG IS NOT NULL;
CREATE UNIQUE INDEX ux_access_account_id_pipeline_code ON CFG_PIPELINE_GRANTS (PROJECT_ID,ACCOUNT_ID,PIPELINE_CODE) WHERE ACTIVE_FLAG='Y' AND ACCOUNT_ID IS NOT NULL AND PIPELINE_CODE IS NOT NULL;
CREATE UNIQUE INDEX ux_access_account_id_tag ON CFG_PIPELINE_GRANTS (PROJECT_ID,ACCOUNT_ID,TAG) WHERE ACTIVE_FLAG='Y' AND ACCOUNT_ID IS NOT NULL AND TAG IS NOT NULL;
CREATE UNIQUE INDEX ux_access_grantee_role_pipeline_code ON CFG_PIPELINE_GRANTS (PROJECT_ID,GRANTEE_ROLE,PIPELINE_CODE) WHERE ACTIVE_FLAG='Y' AND GRANTEE_ROLE IS NOT NULL AND PIPELINE_CODE IS NOT NULL;
CREATE UNIQUE INDEX ux_access_grantee_role_tag ON CFG_PIPELINE_GRANTS (PROJECT_ID,GRANTEE_ROLE,TAG) WHERE ACTIVE_FLAG='Y' AND GRANTEE_ROLE IS NOT NULL AND TAG IS NOT NULL;
CREATE TRIGGER trg_cfg_pipeline_grants_no_delete BEFORE DELETE ON CFG_PIPELINE_GRANTS
BEGIN SELECT RAISE(ABORT, 'CFG_PIPELINE_GRANTS: use ACTIVE_FLAG=N instead of deleting'); END;
CREATE UNIQUE INDEX ux_access_project_group_id ON CFG_PIPELINE_GRANTS (PROJECT_ID,GROUP_ID) WHERE ACTIVE_FLAG='Y' AND GROUP_ID IS NOT NULL AND PIPELINE_CODE IS NULL AND TAG IS NULL;
CREATE UNIQUE INDEX ux_access_project_account_id ON CFG_PIPELINE_GRANTS (PROJECT_ID,ACCOUNT_ID) WHERE ACTIVE_FLAG='Y' AND ACCOUNT_ID IS NOT NULL AND PIPELINE_CODE IS NULL AND TAG IS NULL;
CREATE UNIQUE INDEX ux_access_project_grantee_role ON CFG_PIPELINE_GRANTS (PROJECT_ID,GRANTEE_ROLE) WHERE ACTIVE_FLAG='Y' AND GRANTEE_ROLE IS NOT NULL AND PIPELINE_CODE IS NULL AND TAG IS NULL;
INSERT INTO CFG_PIPELINE_GRANTS (PROJECT_ID,GRANTEE_ROLE,PERMISSION) SELECT PROJECT_ID,'viewer','CAN_VIEW' FROM CFG_PROJECTS;
INSERT INTO CFG_PIPELINE_GRANTS (PROJECT_ID,GRANTEE_ROLE,PERMISSION) SELECT PROJECT_ID,'operator','CAN_RUN' FROM CFG_PROJECTS;
INSERT INTO AUD_CFG_PIPELINE_GRANTS_HISTORY (CHANGE_ID,VALID_FROM,VALID_TO,CURRENT_FLAG,OPERATION,ACTOR,ACTOR_KIND,MIGRATION,PIPELINE_GRANT_ID,GROUP_ID,ACCOUNT_ID,GRANTEE_ROLE,PIPELINE_CODE,TAG,PERMISSION,ACTIVE_FLAG,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,PROJECT_ID)
SELECT (SELECT COALESCE(MAX(m),0) FROM (SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_ACCOUNTS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_API_TOKENS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_BUSINESS_RULES_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_COLUMNS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_GROUPS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_GROUP_MEMBERS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PIPELINES_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PIPELINE_DEPENDENCY_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PIPELINE_GRANTS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_POOLS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_PROJECTS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_SOURCE_COLUMNS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TABLES_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASKS_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASK_DEPENDENCY_HISTORY UNION ALL SELECT MAX(CHANGE_ID) AS m FROM AUD_CFG_TASK_PARAMETERS_HISTORY)) + ROW_NUMBER() OVER (ORDER BY PIPELINE_GRANT_ID),CURRENT_TIMESTAMP,'9999-12-31 23:59:59.999999+00:00','Y','INSERT',etl_craft_actor(),etl_craft_actor_kind(),'engine/0064_project_isolation.sql',PIPELINE_GRANT_ID,GROUP_ID,ACCOUNT_ID,GRANTEE_ROLE,PIPELINE_CODE,TAG,PERMISSION,ACTIVE_FLAG,CREATED_BY,CREATE_DATE,UPDATED_BY,UPDATED_DATE,PROJECT_ID FROM CFG_PIPELINE_GRANTS WHERE PIPELINE_CODE IS NULL AND TAG IS NULL;
